export interface Supplier {
  supplierId: number;
  companyId: number;
  supplierName: string;
  contactName: string | null;
  phone: string | null;
  email: string | null;
  address: string | null;
  active: '1' | '0'; // '1' for active, '0' for inactive
  created_At: string; // ISO 8601 date string
  updated_at: string | null; // ISO 8601 date string
}

export interface SupplierListResponse {
  suppliers: Supplier[];
}

// GET ALL — POST /all_suppliers
export async function getAllSuppliers(companyId: number): Promise<Supplier[]> {
  const res = await fetch(BASE_URL + "/all_suppliers", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ "suppliers": [{ "companyId": companyId }] }),
  });
  if (!res.ok) {
    throw new Error(await res.text());
  }
  const data: SupplierListResponse = await res.json();
  return data.suppliers ?? [];
}

// CREATE — action: 1
export async function createSupplier(payload: Omit<Supplier, "supplierId" | "created_At" | "updated_at">): Promise<Supplier> {
  const res = await fetch(BASE_URL + "/suppliers", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ "suppliers": [{ "action": 1, ...payload }] }),
  });
  if (!res.ok) {
    throw new Error(await res.text());
  }
  return await res.json(); // Assuming backend returns the created supplier
}

// UPDATE — action: 2
export async function updateSupplier(id: number, payload: Partial<Omit<Supplier, "supplierId" | "created_At" | "updated_at"> & { companyId: number }>): Promise<Supplier> {
  const res = await fetch(BASE_URL + "/suppliers", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ "suppliers": [{ "action": 2, "supplierId": id, ...payload }] }),
  });
  if (!res.ok) {
    throw new Error(await res.text());
  }
  return await res.json(); // Assuming backend returns the updated supplier
}

// DELETE — action: 3
export async function deleteSupplier(id: number, companyId: number): Promise<void> {
  const res = await fetch(BASE_URL + "/suppliers", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ "suppliers": [{ "action": 3, "supplierId": id, "companyId": companyId }] }),
  });
  if (!res.ok) {
    throw new Error(await res.text());
  }
}
