} from '../api/supplierApi';
import { InputInputEventDetail, ToggleChangeEventDetail, SearchbarInputEventDetail } from '@ionic/core';

// UTC-7 timezone conversion
const toHermosillo = (utc: string | undefined): string => {
  if (!utc) return '';
  const d = new Date(utc.includes('Z') ? utc : utc + 'Z');
  return new Date(d.getTime() - 7 * 60 * 60 * 1000).toLocaleString('es-MX', {
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
    hour12: false,
  });
};

const SupplierPage: React.FC = () => {
  const { companyId } = useUser();

  const [suppliers, setSuppliers] = useState<Supplier[]>([]);
  const [filteredSuppliers, setFilteredSuppliers] = useState<Supplier[]>([]);
  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState('');
  const [searchTerm, setSearchTerm] = useState('');
  const [showModal, setShowModal] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [currentSupplier, setCurrentSupplier] = useState<Supplier | null>(null);
  const [formState, setFormState] = useState({
    supplierName: '',
    contactName: '',
    phone: '',
    email: '',
    address: '',
    active: true, // boolean for UI, convert to '1'/'0' for API
  });
  const [deleteAlertOpen, setDeleteAlertOpen] = useState(false);
  const [supplierToDeleteId, setSupplierToDeleteId] = useState<number | null>(null);

  // Popover state
  const [popoverState, setPopoverState] = useState<{
    showAlertPopover: boolean;
    showMailPopover: boolean;
    event?: Event;
  }>({ showAlertPopover: false, showMailPopover: false });

  const presentAlertPopover = (e: React.MouseEvent) =>
    setPopoverState({ ...popoverState, showAlertPopover: true, event: e.nativeEvent });
  const dismissAlertPopover = () =>
    setPopoverState({ ...popoverState, showAlertPopover: false });
  const presentMailPopover = (e: React.MouseEvent) =>
    setPopoverState({ ...popoverState, showMailPopover: true, event: e.nativeEvent });
  const dismissMailPopover = () =>
    setPopoverState({ ...popoverState, showMailPopover: false });

  // Infinite Scroll state
  const ITEMS_PER_LOAD = 20;
  const [displayCount, setDisplayCount] = useState(ITEMS_PER_LOAD);

  const contentRef = useRef<HTMLIonContentElement>(null);

  const resetForm = () => {
    setFormState({
      supplierName: '',
      contactName: '',
      phone: '',
      email: '',
      address: '',
      active: true,
    });
    setCurrentSupplier(null);
  };

  const fetchSuppliers = async (isInfiniteScroll = false) => {
    if (!companyId) {
      setError('Company ID not found. Please log in again.');
      return;
    }
    if (!isInfiniteScroll) setLoading(true);
    setError('');
    try {
      const data = await getAllSuppliers(companyId);
      setSuppliers(data);
      setFilteredSuppliers(data);
      if (!isInfiniteScroll) setDisplayCount(ITEMS_PER_LOAD);
    } catch (err) {
      setError((err as Error).message ?? 'Error fetching suppliers');
    } finally {
      setLoading(false);
    }
  };

  useIonViewWillEnter(() => {
    fetchSuppliers();
  }, [companyId]);

  useEffect(() => {
    const lowerCaseSearchTerm = searchTerm.toLowerCase();
    const filtered = suppliers.filter(supplier =>
      supplier.supplierName.toLowerCase().includes(lowerCaseSearchTerm) ||
      (supplier.contactName?.toLowerCase().includes(lowerCaseSearchTerm)) ||
      (supplier.email?.toLowerCase().includes(lowerCaseSearchTerm))
    );
    setFilteredSuppliers(filtered);
    setDisplayCount(ITEMS_PER_LOAD); // Reset display count on new search
  }, [searchTerm, suppliers]);

  const loadMoreItems = () => {
    if (displayCount < filteredSuppliers.length) {
      setTimeout(() => { // Simulate network delay for infinite scroll
        setDisplayCount(prevCount => Math.min(prevCount + ITEMS_PER_LOAD, filteredSuppliers.length));
      }, 500);
    }
  };

  const handleInputChange = (e: CustomEvent<InputInputEventDetail>) => {
    const { name, value } = e.target as HTMLIonInputElement;
    setFormState(prev => ({ ...prev, [name!]: value! }));
  };

  const handleToggleChange = (e: CustomEvent<ToggleChangeEventDetail>) => {
    const { checked } = e.detail;
    setFormState(prev => ({ ...prev, active: checked }));
  };

  const handleSaveSupplier = async () => {
    if (!companyId) {
      setError('Company ID not found. Cannot save supplier.');
      return;
    }

    // Basic validation
    if (!formState.supplierName.trim()) {
      setError('Supplier Name is required.');
      return;
    }

    setSaving(true);
    setError('');

    try {
      const payload = {
        companyId,
        supplierName: formState.supplierName,
        contactName: formState.contactName || null,
        phone: formState.phone || null,
        email: formState.email || null,
        address: formState.address || null,
        active: formState.active ? '1' : '0',
      };

      if (isEditing && currentSupplier?.supplierId) {
        await updateSupplier(currentSupplier.supplierId, payload);
        setError('Proveedor actualizado exitosamente.');
      } else {
        await createSupplier(payload);
        setError('Proveedor creado exitosamente.');
      }
      setShowModal(false);
      resetForm();
      fetchSuppliers(); // Refresh the list
    } catch (err) {
      setError((err as Error).message ?? 'Error saving supplier');
    } finally {
      setSaving(false);
    }
  };

  const handleEditSupplier = (supplier: Supplier) => {
    setCurrentSupplier(supplier);
    setFormState({
      supplierName: supplier.supplierName,
      contactName: supplier.contactName ?? '',
      phone: supplier.phone ?? '',
      email: supplier.email ?? '',
      address: supplier.address ?? '',
      active: supplier.active === '1',
    });
    setIsEditing(true);
    setShowModal(true);
  };

  const handleDeleteClick = (supplierId: number) => {
    setSupplierToDeleteId(supplierId);
    setDeleteAlertOpen(true);
  };

  const handleConfirmDelete = async () => {
    if (supplierToDeleteId === null || !companyId) {
      setError('Invalid supplier or company ID for deletion.');
      return;
    }
    setLoading(true); // Use global loading for delete operation
    setError('');
    try {
      await deleteSupplier(supplierToDeleteId, companyId);
      setError('Proveedor eliminado exitosamente.');
      fetchSuppliers(); // Refresh the list
    } catch (err) {
      setError((err as Error).message ?? 'Error deleting supplier');
    } finally {
      setLoading(false);
      setSupplierToDeleteId(null);
      setDeleteAlertOpen(false);
    }
  };

  return (
    <IonPage className="supplier-page">
      <Header
        presentAlertPopover={presentAlertPopover}
        presentMailPopover={presentMailPopover}
        screenTitle="Proveedores — POS GMO"
      />
      <AlertPopover
        isOpen={popoverState.showAlertPopover}
        event={popoverState.event}
        onDidDismiss={dismissAlertPopover}
      />
      <MailPopover
        isOpen={popoverState.showMailPopover}
        event={popoverState.event}
        onDidDismiss={dismissMailPopover}
      />

      <IonContent fullscreen className="ion-padding" ref={contentRef}>
        <IonSearchbar
          value={searchTerm}
          onIonInput={(e: CustomEvent<SearchbarInputEventDetail>) => setSearchTerm(e.detail.value!)}
          placeholder="Buscar proveedor por nombre, contacto o email"
          debounce={300}
        />

        {loading ? (
          <div className="ion-text-center ion-padding">
            <IonSpinner name="crescent" />
            <IonLabel>Cargando proveedores...</IonLabel>
          </div>
        ) : (
          <IonList className="supplier-list">
            {filteredSuppliers.slice(0, displayCount).map(supplier => (
              <IonItem key={supplier.supplierId} className="supplier-item">
                <IonIcon icon={personCircleOutline} slot="start" className="supplier-icon" />
                <IonLabel>
                  <h2>{supplier.supplierName}</h2>
                  <p>Contacto: {supplier.contactName || 'N/A'}</p>
                  <p>Teléfono: {supplier.phone || 'N/A'}</p>
                  <p>Email: {supplier.email || 'N/A'}</p>
                  <p>Dirección: {supplier.address || 'N/A'}</p>
                  <p>Estado: {supplier.active === '1' ? 'Activo' : 'Inactivo'}</p>
                  <p className="item-date">Creado: {toHermosillo(supplier.created_At)}</p>
                  {supplier.updated_at && <p className="item-date">Actualizado: {toHermosillo(supplier.updated_at)}</p>}
                </IonLabel>
                <IonButton fill="clear" color="medium" onClick={() => handleEditSupplier(supplier)}>
                  <IonIcon icon={create} slot="icon-only" />
                </IonButton>
