                  <IonIcon icon={trash} slot="icon-only" />
                </IonButton>
              </IonItem>
            ))}
            <IonInfiniteScroll
              onIonInfinite={async (ev: CustomEvent<void>) => {
                loadMoreItems();
                (ev.target as HTMLIonInfiniteScrollElement).complete();
              }}
              threshold="100px"
              disabled={displayCount >= filteredSuppliers.length}
            >
              <IonInfiniteScrollContent
                loadingText="Cargando más proveedores..."
                loadingSpinner="crescent"
              />
            </IonInfiniteScroll>
          </IonList>
        )}

        <IonFab vertical="bottom" horizontal="end" slot="fixed">
          <IonFabButton onClick={() => { setIsEditing(false); resetForm(); setShowModal(true); }}>
            <IonIcon icon={add} />
